mapper.insert:
INSERT INTO debate_sessions (
    user_id, original_topic, topic, side_a_label, side_b_label,
    debate_axis, side_a_frame, side_b_frame, selected_round_id, round_title,
    basic_conditions, candidate_run_id, selected_candidate_id, mode, status, peak_reached
)
VALUES (
    #{userId}, #{originalTopic}, #{topic}, #{sideALabel}, #{sideBLabel},
    #{debateAxis}, #{sideAFrame}, #{sideBFrame}, #{selectedRoundId}, #{roundTitle},
    #{basicConditions}, #{candidateRunId}, #{selectedCandidateId}, #{mode}, #{status}, #{peakReached}
)

mapper.update:
UPDATE debate_sessions
SET selected_side = #{selectedSide},
    selected_round_no = #{selectedRoundNo}
WHERE id = #{id}

UPDATE debate_sessions
SET peak_reached = #{peakReached}
WHERE id = #{id}

mapper.select:
SELECT COALESCE(MAX(round_no), 0) + 1
FROM debate_messages
WHERE debate_session_id = #{debateSessionId}

mapper.insert:
INSERT INTO debate_summaries (
    debate_session_id, core_arguments, highlight, decision_criteria, remaining_issue, summary_text
)
VALUES (
    #{debateSessionId}, #{coreArguments}, #{highlight}, #{decisionCriteria}, #{remainingIssue}, #{summaryText}
)

mapper.select:
SELECT id, debate_session_id, core_arguments, highlight, decision_criteria, remaining_issue, summary_text, created_at
FROM debate_summaries
WHERE debate_session_id = #{debateSessionId}

mapper.delete:
DELETE FROM post_votes
WHERE post_id IN (
    SELECT id
    FROM posts
    WHERE debate_session_id = #{debateSessionId}
)

DELETE FROM comments
WHERE post_id IN (
    SELECT id
    FROM posts
    WHERE debate_session_id = #{debateSessionId}
)
